// データ正規化とメタデータ抽出
const items = $input.all();
const normalizedItems = [];

for (const item of items) {
  const data = item.json;
  const source = item.pairedItem?.item?.node || 'unknown';

  try {
    let normalized = {
      id: '',
      title: '',
      url: '',
      description: '',
      publishedAt: '',
      source: source,
      rawData: data,
      contentHash: '',
      extractedAt: new Date().toISOString()
    };

    // ソース別のデータ正規化
    if (source.includes('openai')) {
      // RSS形式の処理
      if (data.rss && data.rss.channel && data.rss.channel.item) {
        const items = Array.isArray(data.rss.channel.item) ? data.rss.channel.item : [data.rss.channel.item];
        for (const rssItem of items) {
          const normalizedItem = {
            ...normalized,
            id: `openai_${rssItem.guid}`,
            title: rssItem.title,
            url: rssItem.link,
            description: rssItem.description,
            publishedAt: rssItem.pubDate,
            source: 'OpenAI RSS'
          };
          normalizedItem.contentHash = require('crypto').createHash('md5').update(normalizedItem.title + normalizedItem.url).digest('hex');
          normalizedItems.push({ json: normalizedItem });
        }
      }
    } else if (source.includes('hackernews')) {
      // Hacker News API形式の処理
      if (Array.isArray(data)) {
        // トップ10記事のみ処理（API制限を考慮）
        const topStories = data.slice(0, 10);
        for (const storyId of topStories) {
          const normalizedItem = {
            ...normalized,
            id: `hn_${storyId}`,
            title: `Hacker News Story ${storyId}`,
            url: `https://news.ycombinator.com/item?id=${storyId}`,
            description: 'Hacker News top story',
            publishedAt: new Date().toISOString(),
            source: 'Hacker News'
          };
          normalizedItem.contentHash = require('crypto').createHash('md5').update(normalizedItem.title + normalizedItem.url).digest('hex');
          normalizedItems.push({ json: normalizedItem });
        }
      }
    } else if (source.includes('reddit')) {
      // Reddit API形式の処理
      if (data.data && data.data.children) {
        for (const post of data.data.children) {
          const postData = post.data;
          const normalizedItem = {
            ...normalized,
            id: `reddit_${postData.id}`,
            title: postData.title,
            url: postData.url,
            description: postData.selftext || postData.title,
            publishedAt: new Date(postData.created_utc * 1000).toISOString(),
            source: 'Reddit r/MachineLearning'
          };
          normalizedItem.contentHash = require('crypto').createHash('md5').update(normalizedItem.title + normalizedItem.url).digest('hex');
          normalizedItems.push({ json: normalizedItem });
        }
      }
    } else if (source.includes('devto')) {
      // Dev.to API形式の処理
      if (Array.isArray(data)) {
        for (const article of data) {
          const normalizedItem = {
            ...normalized,
            id: `devto_${article.id}`,
            title: article.title,
            url: article.url,
            description: article.description,
            publishedAt: article.published_at,
            source: 'Dev.to'
          };
          normalizedItem.contentHash = require('crypto').createHash('md5').update(normalizedItem.title + normalizedItem.url).digest('hex');
          normalizedItems.push({ json: normalizedItem });
        }
      }
    } else if (source.includes('arxiv')) {
      // ArXiv API形式の処理（XML解析が必要だが、簡略版として処理）
      const normalizedItem = {
        ...normalized,
        id: `arxiv_${new Date().getTime()}`,
        title: 'ArXiv AI Papers',
        url: 'https://arxiv.org/list/cs.AI/recent',
        description: 'Recent AI papers from ArXiv',
        publishedAt: new Date().toISOString(),
        source: 'ArXiv'
      };
      normalizedItem.contentHash = require('crypto').createHash('md5').update(normalizedItem.title + normalizedItem.url).digest('hex');
      normalizedItems.push({ json: normalizedItem });
    }
  } catch (error) {
    // エラーログを記録してスキップ
    console.log(`Data normalization error for source ${source}:`, error.message);
  }
}

return normalizedItems;

// 重複除去（タイトル類似度85%以上を除外）
const items = $input.all();
const uniqueItems = [];
const seenHashes = new Set();
const seenTitles = new Map();

// 類似度計算関数
function calculateSimilarity(str1, str2) {
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  const editDistance = levenshteinDistance(shorter, longer);
  return (longer.length - editDistance) / longer.length;
}

function levenshteinDistance(str1, str2) {
  const matrix = [];
  for (let i = 0; i <= str2.length; i++) {
    matrix[i] = [i];
  }
  for (let j = 0; j <= str1.length; j++) {
    matrix[0][j] = j;
  }
  for (let i = 1; i <= str2.length; i++) {
    for (let j = 1; j <= str1.length; j++) {
      if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }
  return matrix[str2.length][str1.length];
}

for (const item of items) {
  const data = item.json;
  let isDuplicate = false;

  // ハッシュベースの完全重複チェック
  if (seenHashes.has(data.contentHash)) {
    isDuplicate = true;
  } else {
    // タイトル類似度チェック
    for (const [existingTitle, existingItem] of seenTitles) {
      const similarity = calculateSimilarity(data.title.toLowerCase(), existingTitle.toLowerCase());
      if (similarity >= 0.85) {
        isDuplicate = true;
        console.log(`Duplicate detected: "${data.title}" vs "${existingTitle}" (similarity: ${similarity.toFixed(2)})`);
        break;
      }
    }
  }

  if (!isDuplicate) {
    seenHashes.add(data.contentHash);
    seenTitles.set(data.title, data);
    uniqueItems.push(item);
  }
}

console.log(`Deduplication: ${items.length} -> ${uniqueItems.length} items (removed ${items.length - uniqueItems.length} duplicates)`);
return uniqueItems;

