// 重要度スコアリング（0-10スケール）
const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const data = item.json;
  let importanceScore = 5; // ベーススコア

  // ソース別重み付け
  const sourceWeights = {
    'OpenAI RSS': 2.0,
    'ArXiv': 1.8,
    'Reddit r/MachineLearning': 1.5,
    'Hacker News': 1.3,
    'Dev.to': 1.0
  };

  importanceScore *= (sourceWeights[data.source] || 1.0);

  // キーワードベーススコアリング
  const highValueKeywords = ['GPT', 'ChatGPT', 'OpenAI', 'breakthrough', 'research', 'AGI', 'LLM', 'transformer'];
  const mediumValueKeywords = ['AI', 'machine learning', 'neural', 'algorithm', 'model'];

  const titleLower = data.title.toLowerCase();
  const descLower = (data.description || '').toLowerCase();

  for (const keyword of highValueKeywords) {
    if (titleLower.includes(keyword.toLowerCase()) || descLower.includes(keyword.toLowerCase())) {
      importanceScore += 1.5;
    }
  }

  for (const keyword of mediumValueKeywords) {
    if (titleLower.includes(keyword.toLowerCase()) || descLower.includes(keyword.toLowerCase())) {
      importanceScore += 0.5;
    }
  }

  // 新しさによるスコア調整
  const publishedDate = new Date(data.publishedAt);
  const now = new Date();
  const hoursDiff = (now - publishedDate) / (1000 * 60 * 60);

  if (hoursDiff <= 24) importanceScore += 1.0; // 24時間以内
  else if (hoursDiff <= 72) importanceScore += 0.5; // 72時間以内

  // スコアを0-10の範囲に正規化
  importanceScore = Math.min(10, Math.max(0, importanceScore));

  scoredItems.push({
    json: {
      ...data,
      importanceScore: Math.round(importanceScore * 10) / 10,
      summary: item.json.choices?.[0]?.message?.content || data.description || 'サマリー生成に失敗しました'
    }
  });
}

// 重要度順にソート
scoredItems.sort((a, b) => b.json.importanceScore - a.json.importanceScore);

console.log(`Scored ${scoredItems.length} items. Top score: ${scoredItems[0]?.json.importanceScore}`);
return scoredItems;

// HTMLメールテンプレート生成
const items = $input.all();
const batchInfo = items[0]?.json || {};

// カテゴリ別グループ化
const categories = {};
for (const item of items) {
  const category = item.json.choices?.[0]?.message?.content?.trim() || 'Other';
  if (!categories[category]) {
    categories[category] = [];
  }
  categories[category].push(item.json);
}

// HTMLテンプレート生成
const currentDate = new Date().toLocaleDateString('ja-JP');
let htmlContent = `
<!DOCTYPE html>
<html>
<head>
