        .article h3 { margin: 0 0 10px 0; color: #2d3748; }
        .article .meta { font-size: 0.9em; color: #718096; margin: 5px 0; }
        .article .summary { margin: 10px 0; }
        .article .score { float: right; background: #667eea; color: white; padding: 2px 8px; border-radius: 12px; font-size: 0.8em; }
        .footer { margin-top: 30px; padding: 20px; background: #f1f5f9; text-align: center; font-size: 0.9em; color: #64748b; }
    </style>
</head>
<body>
    <div class="header">
        <h1>🤖 AI ニュースキュレーション</h1>
        <p>日次ダイジェスト - ${currentDate}</p>
    </div>

    <div style="max-width: 800px; margin: 0 auto; padding: 20px;">
`;

// カテゴリ別記事表示
for (const [category, articles] of Object.entries(categories)) {
  htmlContent += `
        <div class="category">
            <h2>📂 ${category} (${articles.length}件)</h2>
`;

  for (const article of articles) {
    htmlContent += `
            <div class="article">
                <span class="score">${article.importanceScore}</span>
                <h3><a href="${article.url}" target="_blank">${article.title}</a></h3>
                <div class="meta">
                    📅 ${new Date(article.publishedAt).toLocaleDateString('ja-JP')} | 
                    🔗 ${article.source}
                </div>
                <div class="summary">${article.summary}</div>
            </div>
`;
  }

  htmlContent += `        </div>`;
}

htmlContent += `
        <div class="footer">
            <p>🚀 このレポートは AI News Curation Workflow により自動生成されました</p>
            <p>📊 総記事数: ${items.length}件 | ⭐ 平均重要度: ${(items.reduce((sum, item) => sum + item.json.importanceScore, 0) / items.length).toFixed(1)}</p>
        </div>
    </div>
</body>
</html>
`;

return [{
  json: {
    htmlContent: htmlContent,
    subject: `🤖 AI ニュースダイジェスト ${currentDate} (${items.length}件)`,
    articleCount: items.length,
    categories: Object.keys(categories),
    generatedAt: new Date().toISOString()
  }
}];

