// エラーハンドリングとログ記録
const items = $input.all();
const errors = [];
const successes = [];

for (const item of items) {
  if (item.json.error) {
    errors.push({
      step: item.json.step || 'unknown',
      error: item.json.error,
      timestamp: new Date().toISOString()
    });
  } else {
    successes.push({
      step: item.json.step || 'unknown',
      result: 'success',
      timestamp: new Date().toISOString()
    });
  }
}

const logEntry = {
  batchId: $('Initialize Variables').item.json.batchId,
  startTime: $('Initialize Variables').item.json.startTime,
  endTime: new Date().toISOString(),
  totalErrors: errors.length,
  totalSuccesses: successes.length,
  errors: errors,
  successes: successes,
  status: errors.length === 0 ? 'completed' : 'completed_with_errors'
};

console.log('Workflow execution log:', JSON.stringify(logEntry, null, 2));

return [{ json: logEntry }];
